'use strict';
const entryRole=document.documentElement.dataset.entry;
if(entryRole){
 const staff=entryRole==='staff',user=staff?'admin':'lox',pass=staff?'admin1':'lox1';
 document.title='EcoCharge — '+(staff?'Team':'Client')+' sign-in';
 if(staff){document.querySelector('#create-demo-account')?.remove();document.querySelector('#entry-eyebrow').textContent='ECOCHARGE / TEAM OPERATIONS';document.querySelector('#entry-title').innerHTML='Your clients.<br>One clear workspace.';document.querySelector('#entry-description').textContent='Choose your workspace with your team login. FTD agents handle client details and balance changes; administrators manage plans and account settings.';document.querySelector('#entry-benefits').innerHTML='<li>FTD: client details, credits and debits</li><li>Administrator: plans, stations and account settings</li><li>Every balance change has a recorded reason</li>';document.querySelector('#entry-role').textContent='TEAM ACCESS';document.querySelector('#entry-card-title').textContent='Sign in to the team demo';document.querySelector('#entry-hint').innerHTML='<span>FTD: ftd / ftd1</span><br><span>Administrator: admin / admin1</span>';document.querySelector('#entry-submit').innerHTML='Open team workspace <span>→</span>';document.querySelector('#other-entry').href='login/';document.querySelector('#other-entry').textContent='Client? Use client sign-in →';}
 document.querySelector('#show-password').addEventListener('click',e=>{const field=document.querySelector('#entry-password');const show=field.type==='password';field.type=show?'text':'password';e.currentTarget.textContent=show?'Hide':'Show';e.currentTarget.setAttribute('aria-label',show?'Hide password':'Show password')});
 document.querySelector('#entry-form').addEventListener('submit',e=>{e.preventDefault();const enteredUser=document.querySelector('#entry-username').value.trim(),enteredPass=document.querySelector('#entry-password').value,isFtd=staff&&enteredUser==='ftd'&&enteredPass==='ftd1';if(!isFtd&&(enteredUser!==user||enteredPass!==pass)){document.querySelector('#entry-error').textContent='The username or password does not match this demo account.';return}try{sessionStorage.setItem('ecocharge-entry:'+entryRole,JSON.stringify({role:isFtd?'ftd':staff?'admin':'client',user:enteredUser,at:Date.now()}));const allowed=staff?['overview','clients','requests','stations','tariffs','plan']:['dashboard','map','assets','documents','tariffs'];const next=new URL(location).searchParams.get('next');location.assign(window.EcoPlatform.url(staff?'crm':'account',isFtd?'crm/':(staff?'staff/':'client/')+'?tab='+(allowed.includes(next)?next:allowed[0])))}catch{document.querySelector('#entry-error').textContent='Allow browser storage to open the demo workspace.'}});
}
